const baseUrl = import.meta.env.BASE_URL
const fileIcons = {
  pdf: `${baseUrl}icons/pdf.png`,
  txt: `${baseUrl}icons/txt.png`,
  doc: `${baseUrl}icons/doc.png`,
  docx: `${baseUrl}icons/docx.png`,
  zip: `${baseUrl}icons/zip.png`,
  htm: `${baseUrl}icons/htm.png`,
  html: `${baseUrl}icons/html.png`,
  ppt: `${baseUrl}icons/ppt.png`,
  pptx: `${baseUrl}icons/ppt.png`,
  xml: `${baseUrl}icons/xml.png`,
  json: `${baseUrl}icons/json.png`,
  jsonl: `${baseUrl}icons/json.png`,
  md: `${baseUrl}icons/markdown.png`,
  mobi: `${baseUrl}icons/mobi.png`,
  epub: `${baseUrl}icons/epub.png`,
  file: `${baseUrl}icons/file.png`
}

export function getFileType(fileName) {
  if (fileName) {
    return fileName.substring(fileName.lastIndexOf('.') + 1, fileName.length)
  } else {
    return ''
  }
}

export function fileIconRender(type) {
  if (type) {
    return fileIcons[type] || fileIcons['file']
  }
}
